#!/usr/bin/env python3
import gzip, base64
from pathlib import Path
from datetime import datetime, timezone
stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
js = gzip.decompress(base64.b64decode(r''''''))
css = gzip.decompress(base64.b64decode(r''''''))
jp = Path('/opt/liquidgov/assets/juketube.js')
cp = Path('/opt/liquidgov/assets/juketube.css')
jp.with_name(jp.name + '.bak-v5b-' + stamp).write_bytes(jp.read_bytes())
if cp.exists():
    cp.with_name(cp.name + '.bak-v5b-' + stamp).write_bytes(cp.read_bytes())
jp.write_bytes(js)
cp.write_bytes(css)
print('js', len(js), 'css', len(css), 'DONE')
